/// <summary>The functions generated bindings call.</summary>
public static class Weft
{
    /// <summary>SPEC §2.1: false, 0, an empty string and null are falsy; an empty list or object is not.</summary>
    public static bool Truthy(object? value) => value switch
    {
        null => false,
        bool b => b,
        string s => s.Length > 0,
        double d => d != 0 && !double.IsNaN(d),
        int i => i != 0,
        _ => true,
    };

    public static bool Not(object? value) => !Truthy(value);

    /// <summary>A bound <c>hidden</c>. x:Bind turns a <c>bool</c> property into a
    /// <c>Visibility</c>, but not the result of a function.</summary>
    public static Visibility Hide(object? value) => Truthy(value) ? Visibility.Collapsed : Visibility.Visible;

    /// <summary>Tells each item of a list where it sits: <c>path.index</c>, under <c>parent</c>.</summary>
    public static void Place<T>(IList<T> list, object root, object? parent, string path)
    {
        for (var i = 0; i < list.Count; i++)
        {
            if (list[i] is IWeftItem item)
            {
                item.WeftPlace(root, parent, $"{path}.{i}");
            }
        }
