/// <summary>The measuring of <c>ColumnsPanel</c> and <c>ColumnsLayout</c>, which differ only in
/// where their children come from. Arrange uses the column width the last measure found.</summary>
sealed class ColumnGrid
{
    double width;
    int count = 1;

    public Windows.Foundation.Size Measure(IEnumerable<UIElement> children, Windows.Foundation.Size available,
        int columns, double minColumnWidth, double spacing, Thickness p)
    {
        var inner = available.Width - p.Left - p.Right;
        var most = Math.Max(1, columns);
        // Unbounded width, as in a horizontal scroller, has room for every column.
        count = double.IsInfinity(inner)
            ? most
            : Math.Clamp((int)((inner + spacing) / (minColumnWidth + spacing)), 1, most);
        width = double.IsInfinity(inner)
            ? minColumnWidth
            : Math.Max(0, (inner - spacing * (count - 1)) / count);
        var height = 0.0;
        var widest = 0.0;
        foreach (var row in Rows(children))
        {
            var tallest = 0.0;
            foreach (var child in row)
            {
                child.Measure(new Windows.Foundation.Size(width, double.PositiveInfinity));
                tallest = Math.Max(tallest, child.DesiredSize.Height);
                widest = Math.Max(widest, child.DesiredSize.Width);
            }
            height += tallest + (height > 0 ? spacing : 0);
        }
        var across = double.IsInfinity(inner) ? count * widest + spacing * (count - 1) : inner;
        return new Windows.Foundation.Size(across + p.Left + p.Right, height + p.Top + p.Bottom);
    }

    public Windows.Foundation.Size Arrange(IEnumerable<UIElement> children, Windows.Foundation.Size final,
        double spacing, Thickness p)
    {
        var y = p.Top;
        foreach (var row in Rows(children))
        {
            var tallest = row.Max(c => c.DesiredSize.Height);
            for (var i = 0; i < row.Count; i++)
            {
                var x = p.Left + i * (width + spacing);
                row[i].Arrange(new Windows.Foundation.Rect(x, y, width, tallest));
            }
            y += tallest + spacing;
        }
        return final;
    }

    IEnumerable<List<UIElement>> Rows(IEnumerable<UIElement> children) =>
        children.Select((c, i) => (c, i)).GroupBy(t => t.i / count, t => t.c).Select(g => g.ToList());
}

/// <summary>The centre of an element's 3D tilt (SPEC §9, To WinUI): a Weft tilt turns about the
/// element's middle, and a <c>CompositeTransform3D</c> takes its centre in pixels, so this keeps
/// it at half the element's size whenever the size changes.</summary>
public static class Tilt
{
    public static readonly DependencyProperty CenteredProperty = DependencyProperty.RegisterAttached(
        "Centered", typeof(bool), typeof(Tilt), new PropertyMetadata(false, Changed));

    public static bool GetCentered(DependencyObject o) => (bool)o.GetValue(CenteredProperty);
    public static void SetCentered(DependencyObject o, bool value) => o.SetValue(CenteredProperty, value);

    private static void Changed(DependencyObject o, DependencyPropertyChangedEventArgs e)
    {
        if (o is FrameworkElement element && e.NewValue is true && e.OldValue is not true)
        {
            element.SizeChanged += (_, size) =>
            {
                if (element.Transform3D is CompositeTransform3D turn && GetCentered(element))
                {
                    turn.CenterX = size.NewSize.Width / 2;
                    turn.CenterY = size.NewSize.Height / 2;
                }
            };
        }
    }
}

/// <summary>The text value of a control whose own property holds something else (SPEC §9, To
/// WinUI): the <c>Tag</c> of the chosen item, the text of an editable box, a date, a time or a
/// colour. The control shows the value; a choice of the user writes it back and runs the element's
/// <c>change</c>, and a value the view model writes is never a change.</summary>
public static class Choice
{
    public static readonly DependencyProperty ValueProperty = DependencyProperty.RegisterAttached(
        "Value", typeof(string), typeof(Choice), new PropertyMetadata(null, Changed));

    private static readonly DependencyProperty HookedProperty =
        DependencyProperty.RegisterAttached("Hooked", typeof(bool), typeof(Choice), new PropertyMetadata(false));

    // Set while a value is shown, so the events the control raises meanwhile are not the user's.
    private static bool showing;

    public static string? GetValue(DependencyObject o) => (string?)o.GetValue(ValueProperty);
    public static void SetValue(DependencyObject o, string? value) => o.SetValue(ValueProperty, value);

    private static void Changed(DependencyObject o, DependencyPropertyChangedEventArgs _)
    {
        if (o is not FrameworkElement element)
        {
            return;
        }
        if (!(bool)o.GetValue(HookedProperty))
        {
            o.SetValue(HookedProperty, true);
            Hook(element);
        }
        Show(element);
    }

    private static void Show(FrameworkElement element)
    {
        var value = GetValue(element) ?? "";
        showing = true;
        try
        {
            switch (element)
            {
                case ComboBox { IsEditable: true } box:
                    box.Text = value;
                    break;
                case ComboBox box:
                    box.SelectedItem = Tagged(box.Items, value);
                    break;
                case RadioButtons radios:
                    radios.SelectedItem = Tagged(radios.Items, value);
                    break;
                case SelectorBar bar:
                    bar.SelectedItem = Tagged(bar.Items, value) as SelectorBarItem;
                    break;
                case TabView tabs:
                    tabs.SelectedItem = Tagged(tabs.TabItems, value);
                    break;
                case CalendarDatePicker day:
                    day.Date = Weft.Day(value);
                    break;
                case TimePicker time:
                    time.SelectedTime = Weft.Clock(value);
                    break;
                case DropDownButton { Flyout: Flyout { Content: ColorPicker picker } }:
                    picker.Color = Weft.Color(value);
                    break;
                case Panel row:
                    // A `datetime`: both halves, or neither when the text is not one.
                    var parts = value.Split('T');
                    var date = parts.Length == 2 ? Weft.Day(parts[0]) : null;
                    var clock = parts.Length == 2 ? Weft.Clock(parts[1]) : null;
                    var whole = date is not null && clock is not null;
                    foreach (var child in row.Children)
                    {
                        if (child is CalendarDatePicker d)
                        {
                            d.Date = whole ? date : null;
                        }
                        else if (child is TimePicker t)
                        {
                            t.SelectedTime = whole ? clock : null;
                        }
                    }
                    break;
            }
        }
        finally
        {
            showing = false;
        }
    }

    // Shows a value set before the items it names were there.
    internal static void Reshow(FrameworkElement element)
    {
        if (GetValue(element) is not null)
        {
            Show(element);
        }
    }

    private static object? Tagged(IEnumerable<object> items, string value) =>
        items.FirstOrDefault(i => (i as FrameworkElement)?.Tag?.ToString() == value);

    private static string? TagOf(object? item) => (item as FrameworkElement)?.Tag?.ToString();

    private static void Hook(FrameworkElement element)
    {
        switch (element)
        {
            case ComboBox box:
                box.SelectionChanged += (_, _) => Picked(box, TagOf(box.SelectedItem));
                box.TextSubmitted += (_, e) => Picked(box, e.Text);
                break;
            case RadioButtons radios:
                radios.SelectionChanged += (_, _) => Picked(radios, TagOf(radios.SelectedItem));
                break;
            case SelectorBar bar:
                bar.SelectionChanged += (_, _) => Picked(bar, TagOf(bar.SelectedItem));
                break;
            case TabView tabs:
                tabs.SelectionChanged += (_, _) => Picked(tabs, TagOf(tabs.SelectedItem));
                break;
            case CalendarDatePicker day:
                day.DateChanged += (_, e) => Picked(day, e.NewDate is { } d ? Weft.DayText(d) : "");
                break;
            case TimePicker time:
                time.SelectedTimeChanged += (_, e) => Picked(time, e.NewTime is { } t ? Weft.ClockText(t) : "");
                break;
            case DropDownButton { Flyout: Flyout { Content: ColorPicker picker } } button:
                picker.ColorChanged += (_, e) => Picked(button, Weft.Hex(e.NewColor));
                break;
            case Panel row:
                // A literal value is set before the row's pickers are added; they are there once it loads.
                row.Loaded += (_, _) => HookRow(row);
                HookRow(row);
                break;
        }
    }

    private static void HookRow(Panel row)
    {
        foreach (var child in row.Children)
        {
            if (child is not (CalendarDatePicker or TimePicker) || (bool)child.GetValue(HookedProperty))
            {
                continue;
            }
            child.SetValue(HookedProperty, true);
            if (child is CalendarDatePicker day)
            {
                day.DateChanged += (_, _) => Picked(row, Joined(row));
            }
            else if (child is TimePicker time)
            {
                time.SelectedTimeChanged += (_, _) => Picked(row, Joined(row));
            }
        }
        Show(row);
    }

    // A date and a time chosen apart: the half not chosen yet is today, or midnight.
    private static string Joined(Panel row)
    {
        var day = row.Children.OfType<CalendarDatePicker>().FirstOrDefault()?.Date ?? DateTimeOffset.Now;
        var time = row.Children.OfType<TimePicker>().FirstOrDefault()?.SelectedTime ?? TimeSpan.Zero;
        return $"{Weft.DayText(day)}T{Weft.ClockText(time)}";
    }

    private static void Picked(FrameworkElement element, string? value)
    {
        if (showing || value is null || value == GetValue(element))
        {
            return;
        }
        SetValue(element, value);
        On.Changed(element);
    }
}

